local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function b64decode(s)
  local map = {}
  for i = 1, 64 do map[B64:sub(i, i)] = i - 1 end
  local out, acc, n = {}, 0, 0
  for i = 1, #s do
    local c = s:sub(i, i)
    if c == "=" then break end
    local v = map[c]
    if v then
      acc = acc * 64 + v
      n = n + 1
      if n == 4 then
        out[#out + 1] = string.char(
          math.floor(acc / 65536) % 256,
          math.floor(acc / 256) % 256,
          acc % 256)
        acc, n = 0, 0
      end
    end
  end
  if n == 2 then
    out[#out + 1] = string.char(math.floor(acc / 16) % 256)
  elseif n == 3 then
    out[#out + 1] = string.char(math.floor(acc / 4096) % 256, math.floor(acc / 16) % 256)
  end
  return table.concat(out)
end

do
  local map, order = {}, {}
  local blob = b64decode(SEEDDB_B64)
  for off = 16, #blob - 31, 32 do
    local rec = blob:sub(off + 1, off + 32)
    local id = rec:sub(1, 8)
    if not map[id] then order[#order + 1] = id end
    map[id] = rec
  end
  local base = #order

  -- merge whatever this console knows (may be empty or a single entry)
  local console_db = GM9OUT .. "/seeddb.bin"
  local added = 0
  pcall(fs.allow, GM9OUT, { ask_all = true })
  pcall(fs.key_dump, "seeddb.bin", { overwrite = true })
  if exists(console_db) then
    local ok, st = pcall(fs.stat, console_db)
    if ok and st.type == "file" and st.size >= 48 then
      local cdb = fs.read_file(console_db, 0, st.size)
      for off = 16, #cdb - 31, 32 do
        local rec = cdb:sub(off + 1, off + 32)
        local id = rec:sub(1, 8)
        if not map[id] then
          order[#order + 1] = id
          added = added + 1
        end
        map[id] = rec
      end
    end
  end

  local n = #order
  local parts = {
    string.char(n % 256, math.floor(n / 256) % 256, 0, 0),
    string.rep("\0", 12),
  }
  for _, id in ipairs(order) do parts[#parts + 1] = map[id] end
  local ok, err = pcall(write_bytes, OUT .. "/seeddb.bin", table.concat(parts))
  if ok then
    say("seeddb.bin: %d entries (%d built-in + %d from this console)", n, base, added)
    if added == 0 then
      say("  (this console had no additional seeds; the built-in database covers")
      say("   the known public seeds, which is what matters for dumped CIAs)")
    end
  else
    say("seeddb.bin: WARNING could not write (%s)", tostring(err))
  end
end

