    "started: " .. tostring(os.date("%Y-%m-%d %H:%M:%S")) .. "\r\n" ..
    "serial : " .. SERIAL .. "\r\n" ..
    "unit   : " .. UNIT .. "\r\n" ..
    "model  : " .. MODEL .. "\r\n" ..
    "result : " .. string.format("%d keys, %d files, %d failures", stats.keys, stats.files, stats.fails) .. "\r\n" ..
    "\r\n" ..
    table.concat(LOG, "\r\n") .. "\r\n")
end)

